-- Jaga Hak Jakarta: data simulasi (fiktif)
-- 296 rumah tangga + 50 pengajuan dengan sumber_data = 'simulasi'.
-- Dibuat oleh data/simulasi/buat_data_simulasi.py

begin;

do $$
begin
    if exists (select 1 from pengajuan where sumber_data = 'simulasi')
       or exists (select 1 from rumah_tangga where catatan = 'Data simulasi') then
        raise exception 'Data simulasi sudah ada. Hapus dulu kalau ingin mengulang.';
    end if;
end $$;



commit;

-- Cek hasil: rumah tangga simulasi 296, pengajuan simulasi 50
select (select count(*) from rumah_tangga where catatan = 'Data simulasi') as rumah_tangga_simulasi,
       (select count(*) from pengajuan where sumber_data = 'simulasi') as pengajuan_simulasi;
